insert into cat_private.questions(code,payload) values ('CAT001','{"code": "CAT001", "category": "TWK", "topic": "Musyawarah", "stem": "Kelompok minoritas belum berbicara dalam rapat. Tindakan yang tepat?", "options": [{"id": "A", "text": "Mengakhiri rapat", "score": 0}, {"id": "B", "text": "Memberi kesempatan setara sebelum mengambil keputusan", "score": 5}, {"id": "C", "text": "Meminta mereka mengikuti ketua", "score": 0}, {"id": "D", "text": "Menghapus pendapat berbeda", "score": 0}, {"id": "E", "text": "Mengutamakan penyumbang", "score": 0}], "explanation": "Jawaban B memberi semua pihak kesempatan didengar. Musyawarah bukan sekadar menghitung suara; pendapat perlu dipertimbangkan sebelum keputusan dibuat.", "tip": "Baca kata kunci pertanyaan sebelum memilih jawaban.", "source_type": "original", "review_status": "editorial_draft"}'::jsonb) on conflict(code) do nothing;
