insert into cat_private.questions(code,payload) values ('CAT057','{"code": "CAT057", "category": "TIU", "topic": "Kombinasi", "stem": "Pilih dua anggota dari lima orang tanpa jabatan. Banyak cara?", "options": [{"id": "A", "text": "10", "score": 5}, {"id": "B", "text": "20", "score": 0}, {"id": "C", "text": "5", "score": 0}, {"id": "D", "text": "15", "score": 0}, {"id": "E", "text": "25", "score": 0}], "explanation": "Ada 5×4 pasangan berurutan. Karena AB sama dengan BA, bagi 2: 20÷2=10.", "tip": "Baca kata kunci pertanyaan sebelum memilih jawaban.", "source_type": "original", "review_status": "editorial_draft"}'::jsonb) on conflict(code) do nothing;
insert into cat_private.questions(code,payload) values ('CAT058','{"code": "CAT058", "category": "TIU", "topic": "Himpunan", "stem": "Dari 50 peserta, 30 suka matematika, 25 bahasa, 10 keduanya. Tidak suka keduanya?", "options": [{"id": "A", "text": "0", "score": 0}, {"id": "B", "text": "10", "score": 0}, {"id": "C", "text": "15", "score": 0}, {"id": "D", "text": "5", "score": 5}, {"id": "E", "text": "20", "score": 0}], "explanation": "Yang suka setidaknya satu=30+25−10=45. Kurangi dari total: 50−45=5.", "tip": "Baca kata kunci pertanyaan sebelum memilih jawaban.", "source_type": "original", "review_status": "editorial_draft"}'::jsonb) on conflict(code) do nothing;
insert into cat_private.questions(code,payload) values ('CAT059','{"code": "CAT059", "category": "TIU", "topic": "Statistika", "stem": "Median 4,7,9,10,15 adalah ...", "options": [{"id": "A", "text": "7", "score": 0}, {"id": "B", "text": "9", "score": 5}, {"id": "C", "text": "10", "score": 0}, {"id": "D", "text": "8", "score": 0}, {"id": "E", "text": "11", "score": 0}], "explanation": "Data sudah urut. Dari lima angka, posisi tengah adalah angka ketiga, yaitu 9.", "tip": "Baca kata kunci pertanyaan sebelum memilih jawaban.", "source_type": "original", "review_status": "editorial_draft"}'::jsonb) on conflict(code) do nothing;
insert into cat_private.questions(code,payload) values ('CAT060','{"code": "CAT060", "category": "TIU", "topic": "Persentase", "stem": "Penjualan naik dari 120 menjadi 150. Kenaikan persentase?", "options": [{"id": "A", "text": "15%", "score": 0}, {"id": "B", "text": "20%", "score": 0}, {"id": "C", "text": "30%", "score": 0}, {"id": "D", "text": "35%", "score": 0}, {"id": "E", "text": "25%", "score": 5}], "explanation": "Kenaikan 30. Bandingkan dengan nilai awal 120: 30÷120×100%=25%.", "tip": "Baca kata kunci pertanyaan sebelum memilih jawaban.", "source_type": "original", "review_status": "editorial_draft"}'::jsonb) on conflict(code) do nothing;
insert into cat_private.questions(code,payload) values ('CAT061','{"code": "CAT061", "category": "TIU", "topic": "Perbandingan", "stem": "Rasio usia kakak:adik 5:3, jumlah 32 tahun. Selisihnya?", "options": [{"id": "A", "text": "4", "score": 0}, {"id": "B", "text": "6", "score": 0}, {"id": "C", "text": "8", "score": 5}, {"id": "D", "text": "10", "score": 0}, {"id": "E", "text": "12", "score": 0}], "explanation": "Total 8 bagian=32, jadi satu bagian 4. Selisih 2 bagian=8 tahun.", "tip": "Baca kata kunci pertanyaan sebelum memilih jawaban.", "source_type": "original", "review_status": "editorial_draft"}'::jsonb) on conflict(code) do nothing;
insert into cat_private.questions(code,payload) values ('CAT062','{"code": "CAT062", "category": "TIU", "topic": "Skala", "stem": "Skala 1:250.000, jarak peta 4 cm. Jarak sebenarnya?", "options": [{"id": "A", "text": "10 km", "score": 5}, {"id": "B", "text": "1 km", "score": 0}, {"id": "C", "text": "5 km", "score": 0}, {"id": "D", "text": "25 km", "score": 0}, {"id": "E", "text": "100 km", "score": 0}], "explanation": "4×250.000=1.000.000 cm. Satu kilometer 100.000 cm, jadi hasilnya 10 km.", "tip": "Baca kata kunci pertanyaan sebelum memilih jawaban.", "source_type": "original", "review_status": "editorial_draft"}'::jsonb) on conflict(code) do nothing;
insert into cat_private.questions(code,payload) values ('CAT063','{"code": "CAT063", "category": "TIU", "topic": "Spasial", "stem": "Panah atas diputar 90° searah jarum jam tiga kali. Arah akhir?", "options": [{"id": "A", "text": "Atas", "score": 0}, {"id": "B", "text": "Kanan", "score": 0}, {"id": "C", "text": "Bawah", "score": 0}, {"id": "D", "text": "Kiri", "score": 5}, {"id": "E", "text": "Kanan atas", "score": 0}], "explanation": "Putaran pertama kanan, kedua bawah, ketiga kiri. Bayangkan jarum jam bergerak seperempat putaran setiap langkah.", "tip": "Baca kata kunci pertanyaan sebelum memilih jawaban.", "source_type": "original", "review_status": "editorial_draft"}'::jsonb) on conflict(code) do nothing;
insert into cat_private.questions(code,payload) values ('CAT064','{"code": "CAT064", "category": "TIU", "topic": "Spasial", "stem": "Titik (2,1) dicerminkan pada sumbu x=0. Hasil?", "options": [{"id": "A", "text": "(2,−1)", "score": 0}, {"id": "B", "text": "(−2,1)", "score": 5}, {"id": "C", "text": "(1,2)", "score": 0}, {"id": "D", "text": "(−1,2)", "score": 0}, {"id": "E", "text": "(−2,−1)", "score": 0}], "explanation": "Sumbu x=0 adalah sumbu vertikal. Pencerminan membalik kanan-kiri: x berubah tanda, y tetap.", "tip": "Baca kata kunci pertanyaan sebelum memilih jawaban.", "source_type": "original", "review_status": "editorial_draft"}'::jsonb) on conflict(code) do nothing;
insert into cat_private.questions(code,payload) values ('CAT065','{"code": "CAT065", "category": "TIU", "topic": "Urutan", "stem": "A sebelum B, B sebelum C, D setelah C. Urutan benar?", "options": [{"id": "A", "text": "B-A-C-D", "score": 0}, {"id": "B", "text": "A-C-B-D", "score": 0}, {"id": "C", "text": "D-A-B-C", "score": 0}, {"id": "D", "text": "A-B-D-C", "score": 0}, {"id": "E", "text": "A-B-C-D", "score": 5}], "explanation": "Gabungkan syarat: A mendahului B, lalu C, lalu D. Maka A-B-C-D.", "tip": "Baca kata kunci pertanyaan sebelum memilih jawaban.", "source_type": "original", "review_status": "editorial_draft"}'::jsonb) on conflict(code) do nothing;
insert into cat_private.questions(code,payload) values ('CAT066','{"code": "CAT066", "category": "TKP", "topic": "Pelayanan", "stem": "Antrean memanjang karena sistem melambat. Apa tindakan Anda?", "options": [{"id": "A", "text": "Jelaskan gangguan dan koordinasikan perbaikan teknis", "score": 4, "reason": "Bobot 4/5. Arah tindakan sudah tepat, tetapi tindak lanjutnya belum selengkap pilihan berbobot 5."}, {"id": "B", "text": "Bantu warga terdekat tanpa mengatur antrean keseluruhan", "score": 3, "reason": "Bobot 3/5. Ada upaya membantu, tetapi belum menyelesaikan masalah utama secara memadai."}, {"id": "C", "text": "Terus bekerja tanpa informasi", "score": 2, "reason": "Bobot 2/5. Tindakan ini berisiko menunda penyelesaian atau mengabaikan tanggung jawab penting."}, {"id": "D", "text": "Suruh semua warga pulang tanpa solusi", "score": 1, "reason": "Bobot 1/5. Pilihan ini paling lemah karena mengabaikan kebutuhan, integritas, atau keselamatan dalam kasus ini."}, {"id": "E", "text": "Jelaskan gangguan, atur antrean, dan jalankan prosedur cadangan resmi", "score": 5, "reason": "Bobot 5/5. Pilihan paling lengkap untuk kebutuhan kasus ini. Informasi, ketertiban, dan prosedur cadangan membantu layanan tetap berjalan."}], "explanation": "Informasi, ketertiban, dan prosedur cadangan membantu layanan tetap berjalan.", "tip": "Cari tindakan yang membantu, sesuai aturan, dan memiliki tindak lanjut. Bobot ini adalah penilaian latihan, bukan kunci resmi BKN.", "source_type": "original", "review_status": "editorial_draft"}'::jsonb) on conflict(code) do nothing;
