insert into cat_private.questions(code,payload) values ('CAT071','{"code": "CAT071", "category": "TKP", "topic": "Pelayanan", "stem": "Warga lansia kesulitan formulir digital. Anda ...", "options": [{"id": "A", "text": "Jelaskan langkah dan cek pemahaman lalu bantu", "score": 4, "reason": "Bobot 4/5. Arah tindakan sudah tepat, tetapi tindak lanjutnya belum selengkap pilihan berbobot 5."}, {"id": "B", "text": "Berikan petunjuk tertulis saja", "score": 3, "reason": "Bobot 3/5. Ada upaya membantu, tetapi belum menyelesaikan masalah utama secara memadai."}, {"id": "C", "text": "Isi seluruhnya berdasarkan asumsi", "score": 2, "reason": "Bobot 2/5. Tindakan ini berisiko menunda penyelesaian atau mengabaikan tanggung jawab penting."}, {"id": "D", "text": "Suruh membawa keluarga", "score": 1, "reason": "Bobot 1/5. Pilihan ini paling lemah karena mengabaikan kebutuhan, integritas, atau keselamatan dalam kasus ini."}, {"id": "E", "text": "Dampingi sesuai kebutuhan tanpa meminta password atau mengambil persetujuan", "score": 5, "reason": "Bobot 5/5. Pilihan paling lengkap untuk kebutuhan kasus ini. Bantuan harus memudahkan sekaligus menjaga privasi dan kendali pengguna."}], "explanation": "Bantuan harus memudahkan sekaligus menjaga privasi dan kendali pengguna.", "tip": "Cari tindakan yang membantu, sesuai aturan, dan memiliki tindak lanjut. Bobot ini adalah penilaian latihan, bukan kunci resmi BKN.", "source_type": "original", "review_status": "editorial_draft"}'::jsonb) on conflict(code) do nothing;
insert into cat_private.questions(code,payload) values ('CAT072','{"code": "CAT072", "category": "TKP", "topic": "Kerja sama", "stem": "Tim berbeda pendapat tentang metode kerja. Anda ...", "options": [{"id": "A", "text": "Hindari rapat", "score": 1, "reason": "Bobot 1/5. Pilihan ini paling lemah karena mengabaikan kebutuhan, integritas, atau keselamatan dalam kasus ini."}, {"id": "B", "text": "Sepakati kriteria, bandingkan bukti, dan putuskan bersama", "score": 5, "reason": "Bobot 5/5. Pilihan paling lengkap untuk kebutuhan kasus ini. Kriteria objektif membantu tim memilih berdasarkan kebutuhan, bukan status orang."}, {"id": "C", "text": "Dengarkan kedua pihak dan rangkum konsekuensinya", "score": 4, "reason": "Bobot 4/5. Arah tindakan sudah tepat, tetapi tindak lanjutnya belum selengkap pilihan berbobot 5."}, {"id": "D", "text": "Usulkan voting sebelum membahas konsekuensi", "score": 3, "reason": "Bobot 3/5. Ada upaya membantu, tetapi belum menyelesaikan masalah utama secara memadai."}, {"id": "E", "text": "Ikuti yang paling senior saja", "score": 2, "reason": "Bobot 2/5. Tindakan ini berisiko menunda penyelesaian atau mengabaikan tanggung jawab penting."}], "explanation": "Kriteria objektif membantu tim memilih berdasarkan kebutuhan, bukan status orang.", "tip": "Cari tindakan yang membantu, sesuai aturan, dan memiliki tindak lanjut. Bobot ini adalah penilaian latihan, bukan kunci resmi BKN.", "source_type": "original", "review_status": "editorial_draft"}'::jsonb) on conflict(code) do nothing;
insert into cat_private.questions(code,payload) values ('CAT073','{"code": "CAT073", "category": "TKP", "topic": "Profesionalisme", "stem": "Dua tugas mendesak memiliki tenggat bertabrakan. Anda ...", "options": [{"id": "A", "text": "Minta rekan membantu tanpa penyelarasan prioritas", "score": 3, "reason": "Bobot 3/5. Ada upaya membantu, tetapi belum menyelesaikan masalah utama secara memadai."}, {"id": "B", "text": "Kerjakan yang mudah tanpa memberi kabar", "score": 2, "reason": "Bobot 2/5. Tindakan ini berisiko menunda penyelesaian atau mengabaikan tanggung jawab penting."}, {"id": "C", "text": "Tolak keduanya", "score": 1, "reason": "Bobot 1/5. Pilihan ini paling lemah karena mengabaikan kebutuhan, integritas, atau keselamatan dalam kasus ini."}, {"id": "D", "text": "Nilai dampak dan konfirmasi prioritas serta jadwal realistis", "score": 5, "reason": "Bobot 5/5. Pilihan paling lengkap untuk kebutuhan kasus ini. Pemberi tugas perlu mengetahui benturan agar prioritas dapat disepakati."}, {"id": "E", "text": "Susun jadwal dan laporkan risiko terlambat", "score": 4, "reason": "Bobot 4/5. Arah tindakan sudah tepat, tetapi tindak lanjutnya belum selengkap pilihan berbobot 5."}], "explanation": "Pemberi tugas perlu mengetahui benturan agar prioritas dapat disepakati.", "tip": "Cari tindakan yang membantu, sesuai aturan, dan memiliki tindak lanjut. Bobot ini adalah penilaian latihan, bukan kunci resmi BKN.", "source_type": "original", "review_status": "editorial_draft"}'::jsonb) on conflict(code) do nothing;
insert into cat_private.questions(code,payload) values ('CAT074','{"code": "CAT074", "category": "TKP", "topic": "Adaptasi", "stem": "Anda menemukan metode baru yang mungkin membantu layanan. Anda ...", "options": [{"id": "A", "text": "Periksa relevansi dan usulkan uji terbatas dengan persetujuan", "score": 5, "reason": "Bobot 5/5. Pilihan paling lengkap untuk kebutuhan kasus ini. Uji terbatas membantu menilai manfaat dan risiko sebelum diterapkan luas."}, {"id": "B", "text": "Bahas manfaat dan risiko bersama tim", "score": 4, "reason": "Bobot 4/5. Arah tindakan sudah tepat, tetapi tindak lanjutnya belum selengkap pilihan berbobot 5."}, {"id": "C", "text": "Bagikan judul artikel saja", "score": 3, "reason": "Bobot 3/5. Ada upaya membantu, tetapi belum menyelesaikan masalah utama secara memadai."}, {"id": "D", "text": "Simpan tanpa rencana membaca", "score": 2, "reason": "Bobot 2/5. Tindakan ini berisiko menunda penyelesaian atau mengabaikan tanggung jawab penting."}, {"id": "E", "text": "Ganti prosedur sendiri", "score": 1, "reason": "Bobot 1/5. Pilihan ini paling lemah karena mengabaikan kebutuhan, integritas, atau keselamatan dalam kasus ini."}], "explanation": "Uji terbatas membantu menilai manfaat dan risiko sebelum diterapkan luas.", "tip": "Cari tindakan yang membantu, sesuai aturan, dan memiliki tindak lanjut. Bobot ini adalah penilaian latihan, bukan kunci resmi BKN.", "source_type": "original", "review_status": "editorial_draft"}'::jsonb) on conflict(code) do nothing;
insert into cat_private.questions(code,payload) values ('CAT075','{"code": "CAT075", "category": "TKP", "topic": "Integritas", "stem": "Teman meminta didahulukan tanpa alasan sah. Anda ...", "options": [{"id": "A", "text": "Suruh datang saat petugas lain", "score": 2, "reason": "Bobot 2/5. Tindakan ini berisiko menunda penyelesaian atau mengabaikan tanggung jawab penting."}, {"id": "B", "text": "Dahulukan diam-diam", "score": 1, "reason": "Bobot 1/5. Pilihan ini paling lemah karena mengabaikan kebutuhan, integritas, atau keselamatan dalam kasus ini."}, {"id": "C", "text": "Jelaskan aturan ramah dan tunjukkan cara layanan sah yang efisien", "score": 5, "reason": "Bobot 5/5. Pilihan paling lengkap untuk kebutuhan kasus ini. Konsisten pada aturan tidak berarti berhenti membantu; tawarkan jalan yang sah."}, {"id": "D", "text": "Jelaskan antrean dan minta mengikuti urutan", "score": 4, "reason": "Bobot 4/5. Arah tindakan sudah tepat, tetapi tindak lanjutnya belum selengkap pilihan berbobot 5."}, {"id": "E", "text": "Tolak tanpa penjelasan", "score": 3, "reason": "Bobot 3/5. Ada upaya membantu, tetapi belum menyelesaikan masalah utama secara memadai."}], "explanation": "Konsisten pada aturan tidak berarti berhenti membantu; tawarkan jalan yang sah.", "tip": "Cari tindakan yang membantu, sesuai aturan, dan memiliki tindak lanjut. Bobot ini adalah penilaian latihan, bukan kunci resmi BKN.", "source_type": "original", "review_status": "editorial_draft"}'::jsonb) on conflict(code) do nothing;
