insert into cat_private.questions(code,payload) values ('CAT080','{"code": "CAT080", "category": "TKP", "topic": "Sosial budaya", "stem": "Tim berasal dari berbagai daerah. Anda ...", "options": [{"id": "A", "text": "Minta semua meninggalkan kebiasaan daerah", "score": 2, "reason": "Bobot 2/5. Tindakan ini berisiko menunda penyelesaian atau mengabaikan tanggung jawab penting."}, {"id": "B", "text": "Hanya bekerja dengan satu daerah", "score": 1, "reason": "Bobot 1/5. Pilihan ini paling lemah karena mengabaikan kebutuhan, integritas, atau keselamatan dalam kasus ini."}, {"id": "C", "text": "Sepakati cara kerja inklusif dan peran sesuai kompetensi", "score": 5, "reason": "Bobot 5/5. Pilihan paling lengkap untuk kebutuhan kasus ini. Keberagaman dapat mendukung kerja jika komunikasi dan pembagian perannya adil."}, {"id": "D", "text": "Gunakan komunikasi yang dipahami bersama", "score": 4, "reason": "Bobot 4/5. Arah tindakan sudah tepat, tetapi tindak lanjutnya belum selengkap pilihan berbobot 5."}, {"id": "E", "text": "Sopan tetapi menghindari kolaborasi", "score": 3, "reason": "Bobot 3/5. Ada upaya membantu, tetapi belum menyelesaikan masalah utama secara memadai."}], "explanation": "Keberagaman dapat mendukung kerja jika komunikasi dan pembagian perannya adil.", "tip": "Cari tindakan yang membantu, sesuai aturan, dan memiliki tindak lanjut. Bobot ini adalah penilaian latihan, bukan kunci resmi BKN.", "source_type": "original", "review_status": "editorial_draft"}'::jsonb) on conflict(code) do nothing;
insert into cat_private.questions(code,payload) values ('CAT081','{"code": "CAT081", "category": "TKP", "topic": "Jejaring", "stem": "Target tertinggal karena hambatan lintas bagian. Anda ...", "options": [{"id": "A", "text": "Hubungi bagian terkait untuk mencari jalan keluar", "score": 4, "reason": "Bobot 4/5. Arah tindakan sudah tepat, tetapi tindak lanjutnya belum selengkap pilihan berbobot 5."}, {"id": "B", "text": "Tambah jam kerja sendiri tanpa menangani hambatan", "score": 3, "reason": "Bobot 3/5. Ada upaya membantu, tetapi belum menyelesaikan masalah utama secara memadai."}, {"id": "C", "text": "Tunggu bagian lain bergerak", "score": 2, "reason": "Bobot 2/5. Tindakan ini berisiko menunda penyelesaian atau mengabaikan tanggung jawab penting."}, {"id": "D", "text": "Salahkan bagian lain di grup", "score": 1, "reason": "Bobot 1/5. Pilihan ini paling lemah karena mengabaikan kebutuhan, integritas, atau keselamatan dalam kasus ini."}, {"id": "E", "text": "Petakan hambatan dan sepakati tindak lanjut serta penanggung jawab", "score": 5, "reason": "Bobot 5/5. Pilihan paling lengkap untuk kebutuhan kasus ini. Koordinasi memperjelas siapa melakukan apa dan kapan harus selesai."}], "explanation": "Koordinasi memperjelas siapa melakukan apa dan kapan harus selesai.", "tip": "Cari tindakan yang membantu, sesuai aturan, dan memiliki tindak lanjut. Bobot ini adalah penilaian latihan, bukan kunci resmi BKN.", "source_type": "original", "review_status": "editorial_draft"}'::jsonb) on conflict(code) do nothing;
insert into cat_private.questions(code,payload) values ('CAT082','{"code": "CAT082", "category": "TKP", "topic": "Pelayanan", "stem": "Warga meminta layanan di luar kewenangan unit Anda. Anda ...", "options": [{"id": "A", "text": "Katakan bukan urusan kami", "score": 1, "reason": "Bobot 1/5. Pilihan ini paling lemah karena mengabaikan kebutuhan, integritas, atau keselamatan dalam kasus ini."}, {"id": "B", "text": "Pastikan unit tujuan dan jelaskan langkah serta syarat yang diketahui", "score": 5, "reason": "Bobot 5/5. Pilihan paling lengkap untuk kebutuhan kasus ini. Rujukan yang jelas membantu warga melanjutkan proses tanpa harus menebak."}, {"id": "C", "text": "Berikan kontak resmi dan sarankan konfirmasi", "score": 4, "reason": "Bobot 4/5. Arah tindakan sudah tepat, tetapi tindak lanjutnya belum selengkap pilihan berbobot 5."}, {"id": "D", "text": "Sebut unit tujuan tanpa penjelasan", "score": 3, "reason": "Bobot 3/5. Ada upaya membantu, tetapi belum menyelesaikan masalah utama secara memadai."}, {"id": "E", "text": "Tebak unit tujuan", "score": 2, "reason": "Bobot 2/5. Tindakan ini berisiko menunda penyelesaian atau mengabaikan tanggung jawab penting."}], "explanation": "Rujukan yang jelas membantu warga melanjutkan proses tanpa harus menebak.", "tip": "Cari tindakan yang membantu, sesuai aturan, dan memiliki tindak lanjut. Bobot ini adalah penilaian latihan, bukan kunci resmi BKN.", "source_type": "original", "review_status": "editorial_draft"}'::jsonb) on conflict(code) do nothing;
insert into cat_private.questions(code,payload) values ('CAT083','{"code": "CAT083", "category": "TKP", "topic": "Sosial budaya", "stem": "Grup kerja menyebar stereotip agama. Anda ...", "options": [{"id": "A", "text": "Alihkan percakapan tanpa membahas masalah", "score": 3, "reason": "Bobot 3/5. Ada upaya membantu, tetapi belum menyelesaikan masalah utama secara memadai."}, {"id": "B", "text": "Keluar tanpa tindakan", "score": 2, "reason": "Bobot 2/5. Tindakan ini berisiko menunda penyelesaian atau mengabaikan tanggung jawab penting."}, {"id": "C", "text": "Tambahkan candaan serupa", "score": 1, "reason": "Bobot 1/5. Pilihan ini paling lemah karena mengabaikan kebutuhan, integritas, atau keselamatan dalam kasus ini."}, {"id": "D", "text": "Tidak menyebar, ingatkan proporsional, dan laporkan jika serius/berulang", "score": 5, "reason": "Bobot 5/5. Pilihan paling lengkap untuk kebutuhan kasus ini. Pilih respons proporsional yang mencegah diskriminasi dan menjaga keselamatan hubungan kerja."}, {"id": "E", "text": "Ingatkan pengirim secara pribadi", "score": 4, "reason": "Bobot 4/5. Arah tindakan sudah tepat, tetapi tindak lanjutnya belum selengkap pilihan berbobot 5."}], "explanation": "Pilih respons proporsional yang mencegah diskriminasi dan menjaga keselamatan hubungan kerja.", "tip": "Cari tindakan yang membantu, sesuai aturan, dan memiliki tindak lanjut. Bobot ini adalah penilaian latihan, bukan kunci resmi BKN.", "source_type": "original", "review_status": "editorial_draft"}'::jsonb) on conflict(code) do nothing;
insert into cat_private.questions(code,payload) values ('CAT084','{"code": "CAT084", "category": "TKP", "topic": "Digital", "stem": "Aplikasi resmi rusak; ada tawaran aplikasi tak dikenal untuk data warga. Anda ...", "options": [{"id": "A", "text": "Periksa izin dan keamanan melalui pihak berwenang sebelum memakai", "score": 5, "reason": "Bobot 5/5. Pilihan paling lengkap untuk kebutuhan kasus ini. Data warga tidak boleh dijadikan bahan percobaan pada layanan yang belum disetujui."}, {"id": "B", "text": "Laporkan gangguan dan minta prosedur cadangan", "score": 4, "reason": "Bobot 4/5. Arah tindakan sudah tepat, tetapi tindak lanjutnya belum selengkap pilihan berbobot 5."}, {"id": "C", "text": "Hentikan pekerjaan tanpa koordinasi", "score": 3, "reason": "Bobot 3/5. Ada upaya membantu, tetapi belum menyelesaikan masalah utama secara memadai."}, {"id": "D", "text": "Coba sebagian data warga", "score": 2, "reason": "Bobot 2/5. Tindakan ini berisiko menunda penyelesaian atau mengabaikan tanggung jawab penting."}, {"id": "E", "text": "Unggah semua data", "score": 1, "reason": "Bobot 1/5. Pilihan ini paling lemah karena mengabaikan kebutuhan, integritas, atau keselamatan dalam kasus ini."}], "explanation": "Data warga tidak boleh dijadikan bahan percobaan pada layanan yang belum disetujui.", "tip": "Cari tindakan yang membantu, sesuai aturan, dan memiliki tindak lanjut. Bobot ini adalah penilaian latihan, bukan kunci resmi BKN.", "source_type": "original", "review_status": "editorial_draft"}'::jsonb) on conflict(code) do nothing;
