insert into cat_private.questions(code,payload) values ('CAT101','{"code": "CAT101", "category": "TKP", "topic": "Pelayanan", "stem": "Seorang pengguna tunarungu datang tanpa pendamping. Anda ...", "options": [{"id": "A", "text": "Gunakan tulisan sederhana dan cek pemahaman", "score": 4, "reason": "Bobot 4/5. Arah tindakan sudah tepat, tetapi tindak lanjutnya belum selengkap pilihan berbobot 5."}, {"id": "B", "text": "Berikan formulir tanpa penjelasan", "score": 3, "reason": "Bobot 3/5. Ada upaya membantu, tetapi belum menyelesaikan masalah utama secara memadai."}, {"id": "C", "text": "Suruh kembali dengan pendamping", "score": 2, "reason": "Bobot 2/5. Tindakan ini berisiko menunda penyelesaian atau mengabaikan tanggung jawab penting."}, {"id": "D", "text": "Tolak layanan", "score": 1, "reason": "Bobot 1/5. Pilihan ini paling lemah karena mengabaikan kebutuhan, integritas, atau keselamatan dalam kasus ini."}, {"id": "E", "text": "Tanyakan cara komunikasi yang nyaman dan sediakan bantuan aksesibel", "score": 5, "reason": "Bobot 5/5. Pilihan paling lengkap untuk kebutuhan kasus ini. Tanyakan kebutuhan orang tersebut, bukan berasumsi ia tidak mampu mengurus layanan."}], "explanation": "Tanyakan kebutuhan orang tersebut, bukan berasumsi ia tidak mampu mengurus layanan.", "tip": "Cari tindakan yang membantu, sesuai aturan, dan memiliki tindak lanjut. Bobot ini adalah penilaian latihan, bukan kunci resmi BKN.", "source_type": "original", "review_status": "editorial_draft"}'::jsonb) on conflict(code) do nothing;
