insert into cat_private.questions(code,payload) values ('CAT109','{"code": "CAT109", "category": "TKP", "topic": "Sosial budaya", "stem": "Jadwal kegiatan tim bertepatan dengan ibadah sebagian anggota. Anda ...", "options": [{"id": "A", "text": "Diskusikan penyesuaian adil tanpa menghambat tujuan kegiatan", "score": 5, "reason": "Bobot 5/5. Pilihan paling lengkap untuk kebutuhan kasus ini. Penyesuaian yang dibahas bersama menjaga partisipasi dan penghormatan keyakinan."}, {"id": "B", "text": "Cari waktu alternatif bersama koordinator", "score": 4, "reason": "Bobot 4/5. Arah tindakan sudah tepat, tetapi tindak lanjutnya belum selengkap pilihan berbobot 5."}, {"id": "C", "text": "Izinkan absen tanpa menyediakan informasi pengganti", "score": 3, "reason": "Bobot 3/5. Ada upaya membantu, tetapi belum menyelesaikan masalah utama secara memadai."}, {"id": "D", "text": "Minta mereka memilih kerja atau ibadah", "score": 2, "reason": "Bobot 2/5. Tindakan ini berisiko menunda penyelesaian atau mengabaikan tanggung jawab penting."}, {"id": "E", "text": "Mengolok kebutuhan mereka", "score": 1, "reason": "Bobot 1/5. Pilihan ini paling lemah karena mengabaikan kebutuhan, integritas, atau keselamatan dalam kasus ini."}], "explanation": "Penyesuaian yang dibahas bersama menjaga partisipasi dan penghormatan keyakinan.", "tip": "Cari tindakan yang membantu, sesuai aturan, dan memiliki tindak lanjut. Bobot ini adalah penilaian latihan, bukan kunci resmi BKN.", "source_type": "original", "review_status": "editorial_draft"}'::jsonb) on conflict(code) do nothing;
insert into cat_private.questions(code,payload) values ('CAT110','{"code": "CAT110", "category": "TKP", "topic": "Integritas", "stem": "Anda menemukan kuitansi yang tidak cocok dengan transaksi. Anda ...", "options": [{"id": "A", "text": "Ganti angka agar cocok", "score": 2, "reason": "Bobot 2/5. Tindakan ini berisiko menunda penyelesaian atau mengabaikan tanggung jawab penting."}, {"id": "B", "text": "Proses saja agar cepat", "score": 1, "reason": "Bobot 1/5. Pilihan ini paling lemah karena mengabaikan kebutuhan, integritas, atau keselamatan dalam kasus ini."}, {"id": "C", "text": "Verifikasi bukti, laporkan ketidaksesuaian melalui jalur tepat, dan koreksi", "score": 5, "reason": "Bobot 5/5. Pilihan paling lengkap untuk kebutuhan kasus ini. Ketidakcocokan harus diverifikasi, bukan disesuaikan secara fiktif."}, {"id": "D", "text": "Minta klarifikasi penanggung jawab transaksi", "score": 4, "reason": "Bobot 4/5. Arah tindakan sudah tepat, tetapi tindak lanjutnya belum selengkap pilihan berbobot 5."}, {"id": "E", "text": "Tunda pemrosesan tanpa penjelasan", "score": 3, "reason": "Bobot 3/5. Ada upaya membantu, tetapi belum menyelesaikan masalah utama secara memadai."}], "explanation": "Ketidakcocokan harus diverifikasi, bukan disesuaikan secara fiktif.", "tip": "Cari tindakan yang membantu, sesuai aturan, dan memiliki tindak lanjut. Bobot ini adalah penilaian latihan, bukan kunci resmi BKN.", "source_type": "original", "review_status": "editorial_draft"}'::jsonb) on conflict(code) do nothing;
